// Some portions generated by Codex. Differential framing, UTF8 and linear-scan tests.
import assert from 'node:assert/strict';
import {LineSplitter} from './line-splitter.mjs';
let cases=0;
function consume(chunks, fresh) {
 const decoder=new TextDecoder('utf-8',{fatal:true}), splitter=new LineSplitter();
 let carry='', terminal=null; const parsed=[];
 try {
  for(const bytes of chunks) {
   const text=decoder.decode(bytes,{stream:true});
   let lines;
   if(fresh)lines=splitter.push(text);
   else { carry+=text; lines=(function*(){let p;while((p=carry.indexOf('\n'))>=0){const s=carry.slice(0,p);carry=carry.slice(p+1);yield s;}})(); }
   for(const line of lines){if(!line)continue;const r=JSON.parse(line);parsed.push(r);if(r.type==='error')throw Error(JSON.stringify(r));if(r.type==='end'){assert.equal(terminal,null);terminal=r;}}
  }
  const tail=fresh?splitter.finish(decoder.decode()):carry+decoder.decode();
  assert.equal(tail.trim(),'');assert.ok(terminal,'Missing terminal end record');
  return {parsed,error:null};
 }catch(e){return {parsed,error:e.constructor.name};}
}
function check(chunks){assert.deepEqual(consume(chunks,true),consume(chunks,false));cases++;}
const good='\n'+JSON.stringify({type:'rows',values:[[2,'é 漢字 😀',null,'nb'],null]})+'\r\n'+JSON.stringify({type:'end'})+'\n';
assert.equal(consume([Buffer.from(good)],true).error,null);
assert.equal(consume([Buffer.from(good.slice(0,-1))],true).error,'AssertionError');
assert.equal(consume([Buffer.from([0xff])],true).error,'TypeError');
const payloads=[good,good+'  \r\t',good.slice(0,-1),'\n\n'+good,'{"type":"rows"}\n{bad}\n',good+'{"type":"error","message":"oops"}\n','{"type":"rows"}\n','{"type":"end"}\n{"type":"end"}\n',' \n'+good,''];
for(const s of payloads){const b=Buffer.from(s);for(let i=0;i<=b.length;i++)check([b.subarray(0,i),b.subarray(i)]);check([...b].map(x=>Buffer.from([x])));let seed=17;for(let t=0;t<30;t++){const chunks=[];for(let i=0;i<b.length;){seed=(Math.imul(seed,1664525)+1013904223)>>>0;let n=1+seed%19;chunks.push(b.subarray(i,i+n));i+=n;}check(chunks);}}
for(const b of [Buffer.from([0xff]),Buffer.from([0xf0,0x9f]),Buffer.concat([Buffer.from(good),Buffer.from([0xc3,0x28])])])for(let i=0;i<=b.length;i++)check([b.subarray(0,i),b.subarray(i)]);
// Source-level search-region bound; no instrumentation is included in the timed client.
const original=String.prototype.indexOf;let searched=0;
try{String.prototype.indexOf=function(needle,from=0){const n=original.call(this,needle,from);if(needle==='\n')searched+=(n<0?this.length:n+1)-from;return n;};const s=new LineSplitter();for(let i=0;i<10000;i++)assert.deepEqual([...s.push('é😀')],[]);assert.deepEqual([...s.push('\n')],['é😀'.repeat(10000)]);assert.equal(s.finish(),'');assert.equal(searched,30001);}finally{String.prototype.indexOf=original;}
// Lazy emission: a later malformed record does not precede the first rows record.
const lazy=new LineSplitter().push('a\nb\n');assert.deepEqual(lazy.next(),{value:'a',done:false});assert.deepEqual(lazy.next(),{value:'b',done:false});assert.equal(lazy.next().done,true);
console.log(JSON.stringify({status:'passed',differentialCases:cases,linearSearchUnits:searched}));
